CREATE OR REPLACE FUNCTION public.remove_schedule_stage(_id uuid,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.work_stages; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO s FROM public.work_stages WHERE id=_id FOR UPDATE; IF NOT FOUND OR s.removed THEN RAISE EXCEPTION 'Etapa não encontrada.'; END IF; PERFORM id FROM public.work_registry WHERE id=s.work_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.work_records WHERE stage_id=s.id) OR EXISTS(SELECT 1 FROM public.financial_entries WHERE stage_id=s.id) OR EXISTS(SELECT 1 FROM public.work_stages WHERE dependency_id=s.id AND NOT removed) THEN RAISE EXCEPTION 'Esta etapa possui registros ou dependências. Preserve-a ou remova os vínculos antes de excluir.'; END IF; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=s.work_id) AND nullif(trim(_reason),'') IS NULL THEN RAISE EXCEPTION 'Informe o motivo da exclusão.'; END IF; PERFORM set_config('jmg.stage_remove','on',true); UPDATE public.work_stages SET removed=true,schedule_change_reason=_reason WHERE id=s.id; IF EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=s.work_id) THEN PERFORM public.capture_schedule_version(s.work_id,_reason); END IF; END $$;
CREATE TRIGGER removed_stage_guard BEFORE UPDATE OF removed ON public.work_stages FOR EACH ROW EXECUTE FUNCTION public.guard_removed_stage();
CREATE OR REPLACE FUNCTION public.create_schedule(_data jsonb,_work_id uuid DEFAULT NULL,_budget_id uuid DEFAULT NULL,_copy_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; w public.work_registry; b public.budgets; src public.schedules; rows jsonb; mapping jsonb; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM set_config('jmg.schedule_operation','on',true); IF _work_id IS NOT NULL THEN SELECT * INTO w FROM public.work_registry WHERE id=_work_id AND NOT archived FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada.'; END IF; SELECT id INTO sid FROM public.schedules WHERE work_id=w.id; IF sid IS NULL THEN INSERT INTO public.schedules(work_id,name,client_id,client_name,address) VALUES(w.id,w.name,w.client_id,coalesce((SELECT name FROM public.people WHERE id=w.client_id),''),w.address) RETURNING id INTO sid; END IF; IF w.linked_budget_id IS NOT NULL THEN PERFORM public.import_work_schedule(w.id); END IF; RETURN sid; END IF;
IF _copy_id IS NOT NULL THEN SELECT * INTO src FROM public.schedules WHERE id=_copy_id; IF NOT FOUND THEN RAISE EXCEPTION 'Cronograma não encontrado.'; END IF; IF src.work_id IS NULL THEN rows:=src.standalone_stages; ELSE SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY sort),'[]') INTO rows FROM public.work_stages s WHERE work_id=src.work_id AND NOT removed; END IF; SELECT coalesce(jsonb_object_agg(x->>'id',gen_random_uuid()::text),'{}') INTO mapping FROM jsonb_array_elements(rows) x; SELECT coalesce(jsonb_agg((x - 'work_id' - 'budget_section_id' - 'created_by' - 'updated_by' - 'created_at' - 'updated_at')||jsonb_build_object('id',mapping->>(x->>'id'),'dependency_id',mapping->>(x->>'dependency_id'),'progress',0,'status','nao_iniciado','actual_start',NULL,'actual_end',NULL)),'[]') INTO rows FROM jsonb_array_elements(rows) x;
ELSIF _budget_id IS NOT NULL THEN SELECT * INTO b FROM public.budgets WHERE id=_budget_id; IF NOT FOUND THEN RAISE EXCEPTION 'Orçamento não encontrado.'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('id',gen_random_uuid(),'name',bs.title,'sort',bs.sort,'weight',0,'progress',0,'status','nao_iniciado','planned_start',NULL,'planned_end',NULL,'scope_services',(SELECT string_agg(bi.description,E'\n' ORDER BY bi.sort) FROM public.budget_items bi WHERE bi.section_id=bs.id)) ORDER BY bs.sort),'[]') INTO rows FROM public.budget_sections bs WHERE bs.budget_id=b.id;
ELSE rows:='[]'; END IF;
INSERT INTO public.schedules(budget_id,client_id,client_name,name,address,description,planned_start,planned_end,responsible,notes,standalone_stages) VALUES(_budget_id,coalesce(nullif(_data->>'client_id','')::uuid,b.client_id),coalesce(_data->>'client_name',b.client_display,src.client_name,''),coalesce(nullif(_data->>'name',''),b.title,src.name||' · cópia','Novo cronograma'),coalesce(_data->>'address',b.endereco,src.address),_data->>'description',nullif(_data->>'planned_start','')::date,nullif(_data->>'planned_end','')::date,_data->>'responsible',coalesce(_data->>'notes',src.notes),rows) RETURNING id INTO sid;RETURN sid; END $$;
CREATE OR REPLACE FUNCTION public.link_schedule_work(_schedule_id uuid,_work_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.schedules; target uuid; s jsonb; v record; BEGIN IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM id FROM public.work_registry WHERE id=_work_id AND NOT archived FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Obra não encontrada.'; END IF; SELECT * INTO h FROM public.schedules WHERE id=_schedule_id FOR UPDATE; IF NOT FOUND OR h.work_id IS NOT NULL OR h.is_template THEN RAISE EXCEPTION 'Selecione um cronograma avulso, não um modelo.'; END IF; SELECT id INTO target FROM public.schedules WHERE work_id=_work_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.work_stages WHERE work_id=_work_id AND NOT removed) OR EXISTS(SELECT 1 FROM public.work_schedule_versions WHERE work_id=_work_id) THEN RAISE EXCEPTION 'Esta obra já possui etapas ou histórico. Escolha uma obra sem planejamento; nenhum registro foi substituído.'; END IF; PERFORM public.validate_standalone_stages(h.standalone_stages);PERFORM set_config('jmg.schedule_operation','on',true);PERFORM set_config('jmg.schedule_batch','on',true);
FOR s IN SELECT value FROM jsonb_array_elements(h.standalone_stages) LOOP INSERT INTO public.work_stages(id,work_id,name,sort,responsible,planned_start,planned_end,actual_start,actual_end,weight,progress,status,observations,scope_services,schedule_change_reason) VALUES((s->>'id')::uuid,_work_id,s->>'name',coalesce((s->>'sort')::integer,0),s->>'responsible',nullif(s->>'planned_start','')::date,nullif(s->>'planned_end','')::date,nullif(s->>'actual_start','')::date,nullif(s->>'actual_end','')::date,coalesce((s->>'weight')::numeric,0),coalesce((s->>'progress')::numeric,0),coalesce(s->>'status','nao_iniciado'),s->>'observations',s->>'scope_services','Vínculo de cronograma avulso'); END LOOP;
FOR s IN SELECT value FROM jsonb_array_elements(h.standalone_stages) LOOP UPDATE public.work_stages SET dependency_id=nullif(s->>'dependency_id','')::uuid WHERE id=(s->>'id')::uuid;END LOOP;
FOR v IN SELECT * FROM public.schedule_versions WHERE schedule_id=h.id ORDER BY version LOOP INSERT INTO public.work_schedule_versions(work_id,version,stages,notes,reason,created_by,created_at) VALUES(_work_id,v.version,v.stages,v.notes,v.reason,v.created_by,v.created_at); END LOOP;
IF target IS NOT NULL THEN UPDATE public.schedules SET work_id=NULL,archived=true WHERE id=target; END IF; UPDATE public.schedules SET work_id=_work_id,standalone_stages='[]',is_template=false WHERE id=h.id; UPDATE public.work_registry SET schedule_notes=h.notes,schedule_change_reason='Vínculo do cronograma avulso' WHERE id=_work_id;PERFORM set_config('jmg.schedule_batch','off',true); END $$;
CREATE OR REPLACE FUNCTION public.guard_schedule_header() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (new.work_id IS DISTINCT FROM old.work_id OR new.standalone_stages IS DISTINCT FROM old.standalone_stages OR new.notes IS DISTINCT FROM old.notes) AND coalesce(current_setting('jmg.schedule_operation',true),'')<>'on' THEN RAISE EXCEPTION 'Use a operação de edição ou vínculo do cronograma.'; END IF; IF new.work_id IS NOT NULL AND (new.is_template OR jsonb_array_length(new.standalone_stages)>0) THEN RAISE EXCEPTION 'Cronograma vinculado usa somente etapas da obra.'; END IF; IF TG_OP='INSERT' AND (new.work_id IS NOT NULL OR jsonb_array_length(new.standalone_stages)>0) AND coalesce(current_setting('jmg.schedule_operation',true),'')<>'on' AND pg_trigger_depth()<2 THEN RAISE EXCEPTION 'Use Novo Cronograma.'; END IF; new.updated_at:=now();RETURN new; END $$;